import { expr } from "../../engine/tf/index.js";
/** Resolve a foreign root through its graph-declared reference lookup facet. */
export function resolveForeignRef(kind, token, orgRefs, diagnostics, where = "foreign reference") {
    const resolved = orgRefs.resolveForeignRoot(kind, token);
    if (resolved.usedCompatibilityFallback) {
        diagnostics?.push(`${where}: ${kind} "${token.name}" has no namespace; using the graph-declared name compatibility lookup`);
    }
    return {
        value: expr.dataAttr(resolved.resourceType, resolved.tfLabel, ["id"]),
        tfLabel: resolved.tfLabel,
    };
}
